(x, y, t) => {
  const wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10+Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10+Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.03+t*0.5)*5+Math.cos(sy*0.025-t*0.4)*4;
  const wy2 = Math.cos(sy*0.028-t*0.45)*5+Math.sin(sx*0.022+t*0.55)*4;
  const fx = sx+wx2, fy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,-0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,-1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,-0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,1.1],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.085,1.8,-0.5]
  ];
  let aS=0,iS=0,lap=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    lap+=Math.cos(d*f*0.5-t*sp*0.8)*Math.abs(w);
  }
  const act=aS/8,inh=iS/8,laplacian=lap/8;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2+Math.sin(fx*0.06+fy*0.08-t*0.7)*0.15;
  const cx=240,cy=120;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.07-ang*2+t*0.9)*0.3;
  const dist2=Math.sqrt((fx-360)**2+(fy-60)**2),ang2=Math.atan2(fy-60,fx-360);
