  const dist3=Math.sqrt((fx-100)**2+(fy-200)**2),ang3=Math.atan2(fy-200,fx-100);
  const sp3=Math.sin(dist3*0.055+ang3*3-t*1.3)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+sp2+sp3+laplacian*0.4)*2.2);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(fx*0.3+t*3)*Math.sin(fy*0.3-t*2.5)*0.15;
  const blend=reaction*0.6+cell*0.2+micro*0.1+(sp2+sp3)*0.1;
  const v=blend*0.5+0.5;
  const pal=[[12,22,82],[18,55,120],[20,100,130],[25,155,125],[140,190,80],[220,200,60],[230,150,60],[210,100,65],[180,60,80],[130,40,90],[75,25,85],[30,20,75],[12,22,82]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2+Math.abs(laplacian)*0.1;
  const edge=Math.abs(reaction)>0.7?1.15:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-dist*0.003)*0.15;
  const fl=lum*edge+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0
  ];
}
